function uid(){return crypto.randomUUID ? crypto.randomUUID() : 'id-'+Date.now()+'-'+Math.random().toString(16).slice(2)}
function monthNow(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function shiftMonthValue(value,delta){const [y,m]=String(value||monthNow()).split('-').map(Number);const d=new Date(y,m-1+delta,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function monthLabel(value){if(!/^\d{4}-\d{2}$/.test(String(value||'')))return String(value||'');const [y,m]=value.split('-').map(Number);return new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(y,m-1,1)))}
function toast(msg,error=false,actionLabel='',actionFn=null,duration=3200){const t=$('#toast');t.innerHTML='';const span=document.createElement('span');span.textContent=msg;t.appendChild(span);if(actionLabel&&actionFn){const b=document.createElement('button');b.type='button';b.textContent=actionLabel;b.onclick=()=>{clearTimeout(toast._t);t.className='toast';actionFn()};t.appendChild(b)}t.className='toast show'+(error?' error':'');clearTimeout(toast._t);toast._t=setTimeout(()=>t.className='toast',duration)}
function esc(v=''){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
