const TAX_REGIME_LABELS={SN:'SIMPLES NACIONAL',LP:'LUCRO PRESUMIDO',LR:'LUCRO REAL'};
const REGIME_SORT_FILTERS={REGIME_SN:'SN',REGIME_LP:'LP',REGIME_LR:'LR'};
function normalizedTaxRegimeCode(value=''){
 const normalized=String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();
 const compact=normalized.replace(/\s+/g,''),tokens=new Set(normalized.split(/\s+/).filter(Boolean));
 if(compact==='SN'||compact==='SIMPLES'||tokens.has('SN')||compact.includes('SIMPLESNACIONAL')||(tokens.has('SIMPLES')&&tokens.has('NACIONAL')))return 'SN';
 if(compact==='LP'||compact==='PRESUMIDO'||tokens.has('LP')||compact.includes('LUCROPRESUMIDO')||(tokens.has('LUCRO')&&tokens.has('PRESUMIDO')))return 'LP';
 if(compact==='LR'||compact==='REAL'||tokens.has('LR')||compact.includes('LUCROREAL')||(tokens.has('LUCRO')&&tokens.has('REAL')))return 'LR';
 return 'OTHER';
}
function canonicalTaxRegimeLabel(value=''){const code=normalizedTaxRegimeCode(value);return TAX_REGIME_LABELS[code]||String(value||'OUTROS').trim().toUpperCase()||'OUTROS'}
