function formatCnpj(v=''){const d=onlyDigits(v).slice(0,14);if(!d)return '';return d.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d)/,'.$1/$2').replace(/(\d{4})(\d)/,'$1-$2')}
function validCnpj(v=''){const d=onlyDigits(v);if(!d)return true;if(d.length!==14||/^(\d)\1{13}$/.test(d))return false;const n=[...d].map(Number);for(const size of [12,13]){const w=[...Array(size-8)].map((_,i)=>size-7-i).concat([9,8,7,6,5,4,3,2]);const total=n.slice(0,size).reduce((a,x,i)=>a+x*w[i],0);const r=total%11;const check=r<2?0:11-r;if(n[size]!==check)return false}return true}
