function localDuplicate(body,excludeId=''){const owner=body.owner_user_id;const cnpj=onlyDigits(body.cnpj);const dom=String(body.dominio_code||'').trim().toLowerCase();const name=String(body.legal_name||'').trim().toLowerCase().replace(/\s+/g,' ');for(const c of state.companies){if(c.id===excludeId||c.owner_user_id!==owner)continue;if(cnpj&&onlyDigits(c.cnpj)===cnpj)return 'CNPJ já cadastrado para este responsável.';if(dom&&String(c.dominio_code||'').trim().toLowerCase()===dom)return 'Código Domínio já cadastrado para este responsável.';if(!cnpj&&!dom&&String(c.legal_name||'').trim().toLowerCase().replace(/\s+/g,' ')===name)return 'Nome da empresa já cadastrado para este responsável.'}return ''}
