async function acceptServerDataEpoch(value,{clearStaleOutbox=false,lastRestoreAt=''}={}){const next=String(value||'').trim(),prev=cachedDataEpoch(),restored=String(lastRestoreAt||'').trim(),changed=!!(next&&prev&&next!==prev),legacyAfterRestore=!!(next&&!prev&&restored);if(clearStaleOutbox&&(changed||legacyAfterRestore)){try{await idb.clear('outbox')}catch{}}if(next)localStorage.setItem('ht_data_epoch',next);if(restored)localStorage.setItem('ht_last_restore_at',restored);return{changed:changed||legacyAfterRestore,previous:prev,current:next,restored_at:restored}}

const idb={db:null,async open(){if(this.db)return this.db;this.db=await new Promise((res,rej)=>{const r=indexedDB.open('ht-controle-fiscal',7);r.onupgradeneeded=()=>{const d=r.result;for(const [name,key] of [['companies','id'],['checks','key'],['snapshots','key'],['monthlyNotes','key'],['visualMarks','key'],['documents','id'],['adminNotes','id'],['alerts','id'],['users','id'],['periods','key'],['meta','key']])if(!d.objectStoreNames.contains(name))d.createObjectStore(name,{keyPath:key});if(!d.objectStoreNames.contains('outbox'))d.createObjectStore('outbox',{keyPath:'id'});};r.onsuccess=()=>{this.db=r.result;this.db.onversionchange=()=>{try{this.db?.close()}catch{}this.db=null};res(this.db)};r.onerror=()=>rej(r.error)});return this.db},async tx(store,mode='readonly'){const d=await this.open();return d.transaction(store,mode).objectStore(store)},async all(store){const st=await this.tx(store);return await new Promise((res,rej)=>{const r=st.getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})},async put(store,v){const st=await this.tx(store,'readwrite');return await new Promise((res,rej)=>{const r=st.put(v);r.onsuccess=()=>res(v);r.onerror=()=>rej(r.error)})},async del(store,k){const st=await this.tx(store,'readwrite');return await new Promise((res,rej)=>{const r=st.delete(k);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})},async clear(store){const st=await this.tx(store,'readwrite');return await new Promise((res,rej)=>{const r=st.clear();r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})},async bulkPut(store,values){if(!values?.length)return;const db=await this.open();await new Promise((res,rej)=>{const tx=db.transaction(store,'readwrite'),st=tx.objectStore(store);for(const v of values)st.put(v);tx.oncomplete=()=>res();tx.onerror=tx.onabort=()=>rej(tx.error||new Error('Falha ao gravar cache local.'))})},async deleteWhere(store,predicate){const rows=await this.all(store),idStores=new Set(['companies','documents','adminNotes','alerts','users']),keys=rows.filter(predicate).map(v=>v[idStores.has(store)?'id':'key']);if(!keys.length)return;const db=await this.open();await new Promise((res,rej)=>{const tx=db.transaction(store,'readwrite'),st=tx.objectStore(store);for(const k of keys)st.delete(k);tx.oncomplete=()=>res();tx.onerror=tx.onabort=()=>rej(tx.error||new Error('Falha ao atualizar cache local.'))})},close(){try{this.db?.close()}catch{}this.db=null}};

function apiRequestUrl(path=''){let p=String(path||'').trim();if(!p.startsWith('/'))p='/'+p;while(p.startsWith('/api/api/'))p=p.slice(4);return p==='/api'||p.startsWith('/api/')?p:API+p}
async function api(path,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};if(token())headers.Authorization='Bearer '+token();const r=await fetch(apiRequestUrl(path),{...opts,headers});let data={};try{data=await r.json()}catch{}if(!r.ok){const e=new Error(data.error||`Erro ${r.status}`);e.status=r.status;throw e}return data}
async function verifyServerIdentity(){try{const d=await api('/health');return assertServerCompatibility(d)}catch(e){if(e.compatibility)throw e;if(e.status){const x=new Error(`O servidor local não corresponde ao FIX13 esperado (HTTP ${e.status}). Feche o app e execute novamente 02_INICIAR_LOCAL.bat.`);x.compatibility=true;throw x}return null}}
function assertServerCompatibility(data){const app=String(data?.app||'').trim(),build=String(data?.server_build||'').trim(),features=data?.features&&typeof data.features==='object'?data.features:{};if(app!=='ht-controle-fiscal'||build!==APP_BUILD||features.company_order!==true||features.regime_filter!==true||features.general_alerts_v2!==true||features.user_admin_v2!==true||features.competence_lifecycle_v2!==true||features.period_company_membership_v1!==true||features.admin_backup_restore_v2!==true||features.admin_period_override_v1!==true||features.user_delete_transfer_v1!==true||features.company_order_snapshots_v2!==true||features.admin_historical_reopen_v2!==true||features.historical_consistency_v1!==true||features.period_completion_gate_v1!==true){const shown=build?`v${build}`:'sem identificação';const e=new Error(`Interface v${APP_BUILD} incompatível com servidor ${shown}. Feche todas as janelas, execute 02_INICIAR_LOCAL.bat e abra o atalho novamente.`);e.compatibility=true;throw e}return data}
function normalizeCompanyRecord(c){const display=Number(c?.display_order),legacy=Number(c?.sort_order),order=Number.isFinite(display)&&display>0?display:Number.isFinite(legacy)&&legacy>0?legacy:0;return{...c,display_order:order}}
function normalizePeriodRecord(p){let layout={};try{layout=typeof p?.layout_json==='string'?JSON.parse(p.layout_json||'{}'):(p?.layout||{})}catch{}return{...p,layout,key:`${p.owner_user_id}|${p.competence}`}}
function cacheRecordSets(data){return{companies:(data.companies||[]).map(normalizeCompanyRecord),checks:(data.checks||[]).map(c=>({...c,key:`${c.company_id}|${c.competence}|${c.item_id}`})),snapshots:(data.snapshots||[]).map(x=>({...x,key:`${x.company_id}|${x.competence}`})),monthlyNotes:(data.monthly_notes||[]).map(n=>({...n,key:`${n.company_id}|${n.competence}`})),visualMarks:(data.visual_marks||[]).map(m=>({...m,key:`${m.company_id}|${m.competence}|${m.item_id}`})),documents:data.documents||[],adminNotes:data.admin_notes||[],alerts:data.alerts||[],users:data.users||[],periods:(data.periods||[]).map(normalizePeriodRecord)}}
async function snapshotToLocal(data){const sets=cacheRecordSets(data),scope=data.scope_owner_user_id||null,scopedStores=['companies','checks','snapshots','monthlyNotes','visualMarks','documents','adminNotes'];if(!scope){for(const store of [...scopedStores,'alerts','users','periods'])await idb.clear(store)}else{const cachedCompanies=await idb.all('companies'),ids=new Set(cachedCompanies.filter(c=>companyIdKey(c.owner_user_id)===companyIdKey(scope)).map(c=>companyIdKey(c.id)));for(const c of sets.companies)ids.add(companyIdKey(c.id));await idb.deleteWhere('companies',c=>companyIdKey(c.owner_user_id)===companyIdKey(scope));for(const store of scopedStores.filter(x=>x!=='companies'))await idb.deleteWhere(store,row=>ids.has(companyIdKey(row.company_id)));await idb.deleteWhere('periods',row=>companyIdKey(row.owner_user_id)===companyIdKey(scope));await idb.clear('alerts');await idb.clear('users')}for(const [store,values] of Object.entries(sets))await idb.bulkPut(store,values);await idb.put('meta',{key:'server_build',value:data.server_build||''})}
async function loadLocal(scope=state.scope){const allCompanies=await idb.all('companies'),effective=state.user?.role==='ADMIN'?(scope||null):(state.user?.id||null);state.scope=effective;state.companies=effective?allCompanies.filter(c=>companyIdKey(c.owner_user_id)===companyIdKey(effective)):allCompanies;const allSnapshots=await idb.all('snapshots');state.snapshots=effective?allSnapshots.filter(x=>companyIdKey(x.owner_user_id)===companyIdKey(effective)):allSnapshots;const ids=new Set([...state.companies.map(c=>companyIdKey(c.id)),...state.snapshots.map(x=>companyIdKey(x.company_id))]),forScope=rows=>effective?rows.filter(x=>ids.has(companyIdKey(x.company_id))):rows;state.checks=forScope(await idb.all('checks'));state.monthlyNotes=forScope(await idb.all('monthlyNotes'));state.visualMarks=forScope(await idb.all('visualMarks'));state.documents=forScope(await idb.all('documents'));state.adminNotes=forScope(await idb.all('adminNotes'));state.alerts=await idb.all('alerts');state.users=await idb.all('users');const allPeriods=await idb.all('periods');state.periods=effective?allPeriods.filter(x=>companyIdKey(x.owner_user_id)===companyIdKey(effective)):allPeriods}

async function refreshFromServer(scope=null){const q=scope?`?owner_user_id=${encodeURIComponent(scope)}`:'';const data=assertServerCompatibility(await api('/bootstrap'+q));await acceptServerDataEpoch(data.data_epoch);state.user=data.user;state.securityWarnings=data.security_warnings||[];state.passwordResetRequests=data.password_reset_requests||[];state.adminUsers=data.admin_users||data.users||[];localStorage.setItem('ht_user',JSON.stringify(state.user));state.scope=data.scope_owner_user_id||null;await snapshotToLocal(data);await loadLocal(state.scope);return data}
function enterReauthMode(message='Sessão expirada. Entre novamente para sincronizar.',announce=true){localStorage.removeItem('ht_token');localStorage.removeItem('ht_user');$('#appView')?.classList.add('hidden');$('#loginView')?.classList.remove('hidden');if($('#loginUser')&&!$('#loginUser').value)$('#loginUser').value=state.user?.username||state.user?.email||'';if($('#loginPassword'))$('#loginPassword').value='';if($('#loginMsg'))$('#loginMsg').textContent=`${message} As alterações locais foram preservadas.`;setSync('Reautenticação necessária','offline');if(announce)broadcastPeer('auth-required',{message})}
async function bootstrap(scope=null){state.scope=state.user?.role==='ADMIN'?(scope||null):(state.user?.id||null);setSync('Sincronizando…');if(navigator.onLine&&token()){try{await verifyServerIdentity();const sync=await syncOutbox();if(sync?.auth){enterReauthMode(sync.message||'Sessão expirada. Entre novamente para sincronizar.');await loadLocal(state.scope);return}if(sync?.pending){setSync('Alterações pendentes','offline')}else{await refreshFromServer(state.scope);setSync('Sincronizado','ok')}}catch(e){if(e.compatibility){setSync('Versão incompatível','offline');toast(e.message,true,'',null,7000);$('#appView')?.classList.add('hidden');$('#loginView')?.classList.remove('hidden');return}else{setSync('Offline','offline');toast(e.message,true)}}}else setSync('Offline','offline');await loadLocal(state.scope);renderAll();broadcastRefresh()}
function setSync(text,kind=''){const b=$('#syncBadge');if(!b)return;b.textContent=text;b.className='badge '+kind}

async function queue(method,path,body,applyLocal){const op={id:uid(),method,path,body,created_at:new Date().toISOString()};await idb.put('outbox',op);try{if(applyLocal)await applyLocal()}catch(e){await idb.del('outbox',op.id);throw e}setSync('Alterações pendentes','offline');if(navigator.onLine){const result=await syncOutbox();if(result?.rejected){try{await refreshFromServer(state.scope)}catch{}renderAll();broadcastRefresh();throw new Error(result.message||'A alteração foi rejeitada pelo servidor.')}if(result?.auth){enterReauthMode(result.message||'Sessão expirada. Entre novamente para sincronizar.');broadcastRefresh();throw new Error(result.message||'Sessão expirada. Entre novamente para sincronizar.')}if(result?.compatibility){renderAll();broadcastRefresh();throw new Error(result.message||'Servidor incompatível. A alteração local foi preservada para nova tentativa.')}}renderAll();broadcastRefresh()}
let syncPromise=null;
function isCompanyOrderOperation(path=''){const p=apiRequestUrl(path).replace(/\/+$/,'');return ['/api/company-order','/api/companies/reorder','/api/companies/order','/api/reorder-companies'].includes(p)}
async function sendQueuedOperation(op){const opts={method:op.method,body:op.body?JSON.stringify(op.body):undefined};if(!isCompanyOrderOperation(op.path))return api(op.path,opts);const candidates=[op.path,'/company-order','/companies/reorder','/companies/order','/reorder-companies'],seen=new Set();let last=null;for(const candidate of candidates){const normalized=apiRequestUrl(candidate);if(seen.has(normalized))continue;seen.add(normalized);try{return await api(normalized,opts)}catch(e){last=e;if(e.status!==404)throw e}}const e=new Error('O servidor ativo não oferece a rota de reordenação esperada. A nova ordem ficou preservada localmente; execute 02_INICIAR_LOCAL.bat e sincronize novamente.');e.status=404;e.compatibility=true;e.preserveOutbox=true;e.cause=last;throw e}
async function syncOutboxUnlocked(){if(!navigator.onLine||!token())return{offline:true};const ops=(await idb.all('outbox')).sort((a,b)=>a.created_at.localeCompare(b.created_at));if(!ops.length){setSync('Sincronizado','ok');return{ok:true,count:0}}setSync(`Sincronizando ${ops.length}…`);for(const op of ops){try{await sendQueuedOperation(op);await idb.del('outbox',op.id)}catch(e){if(e.status===401){setSync('Sessão expirada','offline');return{auth:true,message:e.message}}if(e.compatibility||e.preserveOutbox){setSync('Servidor incompatível','offline');return{pending:true,compatibility:true,message:e.message}}if(e.status&&e.status>=400&&e.status<500){await idb.del('outbox',op.id);setSync('Alteração rejeitada','offline');const opLabel=`${op.method||'POST'} ${apiRequestUrl(op.path||'')}`;toast(`Alteração não sincronizada (${opLabel}): ${e.message}`,true);return{rejected:true,message:`${e.message} [${opLabel}]`}}setSync('Alterações pendentes','offline');toast('Servidor indisponível. A alteração ficou salva para sincronizar depois.',true);return{pending:true,message:e.message}}}setSync('Sincronizado','ok');return{ok:true,count:ops.length}}
async function syncOutbox(){if(syncPromise)return syncPromise;const runner=()=>syncOutboxUnlocked();syncPromise=(navigator.locks?.request?navigator.locks.request('ht-controle-fiscal-outbox',{mode:'exclusive'},runner):runner());try{return await syncPromise}finally{syncPromise=null}}

function showApp(){ $('#loginView').classList.add('hidden');$('#appView').classList.remove('hidden');ensureAlertPolling();$('#userLabel').textContent=`${state.user.display_name} · ${state.user.role==='ADMIN'?(state.user.is_primary_admin?'Administrador principal':'Administrador'):'Usuário'}`;const admin=state.user.role==='ADMIN';for(const id of ['adminBtn','adminDashboardBtn','adminHistoryBtn','deleteAllCompaniesBtn'])$('#'+id)?.classList.toggle('hidden',!admin);$('#ownerField').classList.toggle('hidden',!admin);$('#companyOwnerLabel').classList.toggle('hidden',!admin);$('#homeBtn')?.classList.toggle('hidden',!CHECKLIST_WINDOW);$('#nativeFullscreenBtn')?.classList.add('hidden');$('#companyChecklistPanelPopout')?.classList.toggle('hidden',COMPANY_PANEL_WINDOW);document.body.classList.toggle('checklist-window-mode',CHECKLIST_WINDOW);document.body.classList.toggle('company-panel-window-mode',COMPANY_PANEL_WINDOW);if(CHECKLIST_WINDOW)document.title='Checklist — H. Teixeira Controle Fiscal';if(COMPANY_PANEL_WINDOW)document.title='Checklist da empresa — H. Teixeira Controle Fiscal';applyCompanyPanelViewPrefs();}
