function applyGridMode(){const card=$('#gridCard'),btn=$('#compactBtn');if(!card||!btn)return;card.classList.toggle('compact-grid',state.compact);btn.textContent=state.compact?'Modo detalhado':'Modo compacto';btn.setAttribute('aria-pressed',String(state.compact))}
function applyTheme(){const theme=state.theme==='dark'?'dark':'light';document.documentElement.dataset.theme=theme;const btn=$('#themeBtn');if(btn){btn.textContent=theme==='dark'?'Modo claro':'Modo escuro';btn.setAttribute('aria-pressed',String(theme==='dark'))}const meta=document.querySelector('meta[name=theme-color]');if(meta)meta.content=theme==='dark'?'#10181e':'#183b4e'}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('ht_theme',state.theme);applyTheme()}
function renderOwners(){if(state.user.role!=='ADMIN')return;const sel=$('#ownerSelect');const current=state.scope||'';sel.innerHTML=`<option value="">Todos os usuários</option>`+state.users.filter(u=>u.active&&u.role==='USER').map(u=>`<option value="${u.id}">${esc(u.display_name)}</option>`).join('');sel.value=current;$('#companyOwner').innerHTML=state.users.filter(u=>u.active&&u.role==='USER').map(u=>`<option value="${u.id}">${esc(u.display_name)}</option>`).join('')}
function localTodayIso(){const d=new Date(),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function alertTargetIds(a){if(Array.isArray(a?.target_user_ids))return a.target_user_ids.map(String);try{const v=JSON.parse(a?.target_user_ids_json||'[]');return Array.isArray(v)?v.map(String):[]}catch{return[]}}
function alertRuntimeStatus(a,today=localTodayIso()){if(a?.deleted===true||a?.deleted===1)return'DELETED';if(a?.active===false||a?.active===0)return'INACTIVE';const start=String(a?.starts_on||''),end=String(a?.ends_on||'');if(start&&start>today)return'SCHEDULED';if(end&&end<today)return'ENDED';return'ACTIVE'}
function alertTargetsCurrentUser(a){if(a?.target_all===undefined||a?.target_all===true||a?.target_all===1)return true;return alertTargetIds(a).includes(String(state.user?.id||''))}
function alertVisibleNow(a){return alertRuntimeStatus(a)==='ACTIVE'&&alertTargetsCurrentUser(a)}
function alertStatusLabel(status){return{ACTIVE:'Ativo agora',SCHEDULED:'Agendado',ENDED:'Encerrado',INACTIVE:'Pausado',DELETED:'Excluído'}[status]||status}
function alertSeverityLabel(severity){return{INFO:'Informativo',WARNING:'Atenção',CRITICAL:'Crítico'}[severity]||'Informativo'}
function alertDatePt(value){if(!value)return'';const [y,m,d]=String(value).split('-');return y&&m&&d?`${d}/${m}/${y}`:String(value)}
function alertValidityText(a){const start=alertDatePt(a?.starts_on),end=alertDatePt(a?.ends_on);if(start&&end)return`${start} a ${end}`;if(start)return`a partir de ${start}`;if(end)return`até ${end}`;return'Sem prazo final'}
function alertAudienceText(a){if(a?.target_all===undefined||a?.target_all===true||a?.target_all===1)return'Todos os usuários';const names=(a?.target_users||[]).map(x=>x.display_name).filter(Boolean);if(names.length)return names.join(', ');const ids=alertTargetIds(a);return ids.map(id=>state.users.find(u=>String(u.id)===String(id))?.display_name||'Usuário indisponível').join(', ')||'Nenhum usuário'}
function alertFontSize(a){const n=Number.parseInt(a?.font_size,10);return Number.isFinite(n)?Math.max(ALERT_FONT_MIN,Math.min(ALERT_FONT_MAX,n)):ALERT_FONT_DEFAULT}
function alertItemHtml(a){const severity=String(a?.severity||'INFO').toLowerCase(),classes=['alert-led-item',`severity-${severity}`,a?.is_bold?'is-bold':'',a?.highlight_yellow?'is-highlighted':''].filter(Boolean).join(' '),message=String(a?.message||'').trim();return`<span class="${classes}" style="--alert-item-font:${alertFontSize(a)}px"><span class="alert-led-level">${esc(alertSeverityLabel(a?.severity))}</span><span class="alert-led-title">${esc(a?.title||'Alerta')}</span>${message?`<span class="alert-led-message">${esc(message)}</span>`:''}</span><span class="alert-led-separator" aria-hidden="true">◆</span>`}
function renderAlerts(){const box=$('#alertsBar');if(!box)return;const icon={INFO:'i',WARNING:'!',CRITICAL:'!!'},security=(state.securityWarnings||[]),visible=(state.alerts||[]).filter(alertVisibleNow),securityHtml=security.length?`<div class="security-alerts">${security.map(a=>`<div class="alert-banner ${(a.severity||'INFO').toLowerCase()}"><span class="alert-symbol">${icon[a.severity]||'i'}</span><strong>${esc(a.title)}</strong><span>${esc(a.message||'')}</span></div>`).join('')}</div>`:'',paused=sessionStorage.getItem('ht_alert_ticker_paused')==='1';let tickerHtml='';if(visible.length){const group=visible.map(alertItemHtml).join(''),chars=visible.reduce((n,a)=>n+String(a.title||'').length+String(a.message||'').length+30,0),duration=Math.max(20,Math.min(110,Math.round(chars/7)));tickerHtml=`<div class="alert-led-bar" role="region" aria-label="Alertas gerais ativos"><span class="alert-led-fixed-label">ALERTA GERAL</span><div class="alert-led-viewport"><div class="alert-led-track ${paused?'is-paused':''}" style="--alert-ticker-duration:${duration}s"><span class="alert-led-group">${group}</span><span class="alert-led-group" aria-hidden="true">${group}</span></div></div><button type="button" class="alert-led-pause" data-alert-ticker-pause title="${paused?'Retomar':'Pausar'} rolagem" aria-label="${paused?'Retomar':'Pausar'} rolagem">${paused?'▶':'Ⅱ'}</button></div>`}box.innerHTML=securityHtml+tickerHtml;box.classList.toggle('hidden',!securityHtml&&!tickerHtml);const pause=box.querySelector('[data-alert-ticker-pause]');if(pause)pause.onclick=()=>{sessionStorage.setItem('ht_alert_ticker_paused',paused?'0':'1');renderAlerts()}}
async function refreshAlertsOnly(silent=true){if(!state.user||!token()||!navigator.onLine)return false;try{const data=assertServerCompatibility(await api('/alerts'));await idb.clear('alerts');await idb.bulkPut('alerts',data.alerts||[]);state.alerts=data.alerts||[];renderAlerts();if(state.user.role==='ADMIN'&&$('#adminDialog')?.open)renderAdminAlerts();return true}catch(e){if(e.status===401){enterReauthMode(e.message||'Sessão expirada. Entre novamente para receber alertas.');return false}if(!silent)toast(e.message,true);return false}}
function ensureAlertPolling(){if(alertPollTimer)return;alertPollTimer=setInterval(()=>refreshAlertsOnly(true),30000)}
function checkMap(){const m=new Map();for(const c of state.checks)m.set(`${c.company_id}|${c.competence}|${c.item_id}`,c);return m}
function snapshotMap(){const m=new Map();for(const x of state.snapshots)m.set(`${x.company_id}|${x.competence}`,x);return m}
function monthlyNoteMap(){const m=new Map();for(const x of state.monthlyNotes)m.set(`${x.company_id}|${x.competence}`,x);return m}
function visualMarkMap(){const m=new Map();for(const x of state.visualMarks)m.set(`${x.company_id}|${x.competence}|${x.item_id}`,x);return m}
function documentCountMap(){const m=new Map();for(const x of state.documents||[])m.set(x.company_id,(m.get(x.company_id)||0)+1);return m}
function activeAdminNotes(companyId,comp,itemId=null){return (state.adminNotes||[]).filter(n=>n.active!==false&&n.company_id===companyId&&n.competence===comp&&(itemId===null||n.item_id===itemId)).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')))}
function adminNoteCountMap(comp){const m=new Map();for(const n of state.adminNotes||[]){if(n.active===false||n.competence!==comp)continue;m.set(n.company_id,(m.get(n.company_id)||0)+1)}return m}
function adminNoteTypeLabel(type){return type==='DIRECTIVE'?'Determinação':type==='RECORD'?'Registro':'Recado'}
function ownerName(userId){return state.users.find(u=>u.id===userId)?.display_name||''}
function companyIdKey(value){return String(value??'')}
function currentCompetenceValue(){return $('#competenceInput')?.value||monthNow()}
function snapshotAsCompany(snap){return{id:snap.company_id,owner_user_id:snap.owner_user_id,legal_name:snap.legal_name||'',cnpj:snap.cnpj||'',dominio_code:snap.dominio_code||'',tax_regime:snap.tax_regime||'OUTROS',envio:snap.envio||'',particularities:snap.particularities||'',notes:snap.notes||'',checklist:Array.isArray(snap.checklist)?snap.checklist:[],display_order:Number(snap.display_order)||0,deleted:false,_snapshot:true}}
function periodBaseCompanies(comp=currentCompetenceValue()){const owner=currentPeriodOwner(),snaps=(state.snapshots||[]).filter(x=>x.competence===comp&&(!owner||companyIdKey(x.owner_user_id)===companyIdKey(owner)));if(owner&&ownerHasPeriods(owner)&&!periodFor(comp,owner))return[];if(owner&&periodFor(comp,owner))return snaps.map(snapshotAsCompany);if(!owner&&state.user?.role==='ADMIN'){const periodOwners=new Set((state.periods||[]).filter(p=>p.competence===comp).map(p=>companyIdKey(p.owner_user_id))),snapOwners=new Map();for(const snap of snaps){const key=companyIdKey(snap.owner_user_id);if(!snapOwners.has(key))snapOwners.set(key,[]);snapOwners.get(key).push(snapshotAsCompany(snap))}const out=[];for(const [key,rows] of snapOwners)if(periodOwners.has(key))out.push(...rows);out.push(...(state.companies||[]).filter(c=>!periodOwners.has(companyIdKey(c.owner_user_id))));return out}return state.companies||[]}
function companyById(companyId){const key=companyIdKey(companyId),comp=currentCompetenceValue(),fromPeriod=periodBaseCompanies(comp).find(c=>companyIdKey(c.id)===key);return fromPeriod||state.companies.find(c=>companyIdKey(c.id)===key)||null}
function currentPeriodOwner(){return state.user?.role==='ADMIN'?(state.scope||''):(state.user?.id||'')}
function periodFor(comp=$('#competenceInput')?.value||monthNow(),owner=currentPeriodOwner()){if(!owner)return null;return(state.periods||[]).find(p=>companyIdKey(p.owner_user_id)===companyIdKey(owner)&&p.competence===comp)||null}
function ownerHasPeriods(owner=currentPeriodOwner()){return !!owner&&(state.periods||[]).some(p=>companyIdKey(p.owner_user_id)===companyIdKey(owner))}
function periodStatus(comp=$('#competenceInput')?.value||monthNow()){return String(periodFor(comp)?.status||'OPEN').toUpperCase()}
/* SALVARFECHAR01: da competência 11/2026 em diante, "Salvar" só grava e "Fechar Apuração" encerra o período */const FECHAMENTO_SEPARADO_DESDE='2026-11';function fechamentoSeparado(comp=currentCompetenceValue()){return String(comp||'')>=FECHAMENTO_SEPARADO_DESDE}function apuracaoEncerrada(comp=currentCompetenceValue()){return fechamentoSeparado(comp)?'Apuração fechada':'Apuração salva'}
function periodIsClosed(comp=$('#competenceInput')?.value||monthNow()){return periodFor(comp)?.status==='CLOSED'}
function periodIsMutable(comp=$('#competenceInput')?.value||monthNow()){const owner=currentPeriodOwner();if(owner&&ownerHasPeriods(owner)&&!periodFor(comp,owner))return false;return !periodIsClosed(comp)}
function periodHasLater(comp=$('#competenceInput')?.value||monthNow(),owner=currentPeriodOwner()){return !!owner&&(state.periods||[]).some(p=>companyIdKey(p.owner_user_id)===companyIdKey(owner)&&String(p.competence||'')>String(comp||''))}
/* HISTEDIT01: vale para qualquer usuário (antes só ADM) */function historicalEditMode(comp=currentCompetenceValue()){return !!state.user&&periodStatus(comp)==='REOPENED'&&periodHasLater(comp)}
function ensurePeriodEditable(message=fechamentoSeparado()?'Esta apuração está fechada. Use “Reabrir apuração” antes de alterar dados.':'Esta apuração está salva e bloqueada. Use “Reabrir apuração” antes de alterar dados.'){if(periodIsMutable())return confirmLaterCompetence();toast(message,true,'',null,5200);return false}/* OPENCOMP01: competência em aberto mais antiga do responsável + aviso ao lançar em mês posterior */function earliestOpenCompetence(owner=currentPeriodOwner()){if(!owner)return null;const list=(state.periods||[]).filter(p=>companyIdKey(p.owner_user_id)===companyIdKey(owner)&&String(p.status||'').toUpperCase()!=='CLOSED').map(p=>String(p.competence||'')).filter(v=>/^\d{4}-\d{2}$/.test(v)).sort();return list[0]||null}function goToOpenCompetence(open,msg){$('#competenceInput').value=open;localStorage.setItem('ht_competence',open);renderAll();if(msg)toast(msg,false,'',null,6500)}function confirmLaterCompetence(comp=currentCompetenceValue(),opts={}){const owner=currentPeriodOwner(),open=earliestOpenCompetence(owner);if(!open||!(String(open)<String(comp)))return true;const key=`${owner}|${comp}|${open}`;if(!opts.always&&state.laterCompAck===key)return true;const acao=opts.action||'lançando';const ok=confirm(`ATENÇÃO - COMPETÊNCIA\n\nVocê está ${acao} em ${monthLabel(comp).toUpperCase()}, mas a competência ${monthLabel(open).toUpperCase()} ainda está EM ABERTO.\n\nOK = continuar em ${monthLabel(comp)}.\nCancelar = não ${opts.always?'salvar':'lançar'} e ir para ${monthLabel(open)}.`);if(ok){if(!opts.always)state.laterCompAck=key;return true}goToOpenCompetence(open,`Você foi levado para ${monthLabel(open)} (competência em aberto). Nada foi ${opts.always?'salvo':'lançado'} em ${monthLabel(comp)}.`);return false}function openCompetenceAtStartup(){try{if(VIEW_PARAMS.get('competence')||AUXILIARY_WINDOW)return;const open=earliestOpenCompetence();if(open&&open!==currentCompetenceValue())goToOpenCompetence(open,`Abrindo em ${monthLabel(open)}: é a competência em aberto.`)}catch(e){console.warn(e)}}
async function ensureAdminPeriodEditable(actionLabel='alterar esta apuração'){if(periodIsMutable())return confirmLaterCompetence();const comp=currentCompetenceValue(),owner=currentPeriodOwner(),p=periodFor(comp,owner);if(state.user?.role!=='ADMIN'||!owner||!p||p.status!=='CLOSED'){ensurePeriodEditable();return false}if(!confirm(`A apuração de ${monthLabel(comp)} está ${fechamentoSeparado(comp)?'fechada':'salva'} e protegida.\n\nComo administrador, deseja reabri-la para ${actionLabel}?\n\nA reabertura ficará registrada e o período deverá ser ${fechamentoSeparado(comp)?'fechado':'salvo'} novamente ao concluir as alterações.`))return false;try{await flushBeforePeriodAction();await api('/competences/reopen',{method:'POST',body:JSON.stringify({competence:comp,owner_user_id:owner})});await refreshFromServer(state.scope);renderAll();toast(`${monthLabel(comp)} reaberta para edição administrativa.`);broadcastRefresh();return true}catch(e){toast(e.message,true,'',null,6000);return false}}
function periodSavedMeta(comp=$('#competenceInput')?.value||monthNow()){const p=periodFor(comp);if(!p?.saved_at)return'';const who=state.users.find(u=>u.id===p.saved_by)?.display_name||'';return `${new Date(p.saved_at).toLocaleString('pt-BR')}${who?` · ${who}`:''}`}
function companyActionMenuHtml(base,monthly,monthlyClass,markBtnClass,adminNoteCount){const open=companyIdKey(state.companyActionsOpenId)===companyIdKey(base.id);return `<div class="company-actions-shell ${open?'actions-open':''}"><button type="button" class="company-actions-toggle" data-toggle-company-actions="${base.id}" aria-expanded="${open?'true':'false'}" title="${open?'Recolher ações':'Abrir ações da empresa'}">${open?'×':'⋯'}</button><div class="company-actions ${open?'':'hidden'}" data-company-actions-panel="${base.id}"><button data-edit-company="${base.id}">Editar</button><button data-history-company="${base.id}" class="ghost">Hist.</button><button data-monthly-note-company="${base.id}" class="ghost monthly-note-btn ${monthlyClass}" title="Pendência / observação da competência">${monthly?.is_pending?'! Pend.':monthly?.note?'Obs.':'Pend.'}</button><button data-row-highlight-company="${base.id}" class="ghost row-highlight-btn ${markBtnClass}" title="Grifar linha desta competência">Grifo</button><button data-company-checklist-panel="${base.id}" class="ghost company-focus-btn" title="Abrir checklist desta empresa" aria-label="Abrir checklist desta empresa">☑</button>${state.user.role==='ADMIN'?`<button data-admin-note-company="${base.id}" class="ghost admin-note-btn ${adminNoteCount?'has-note':''}" title="Nota do administrador">ADM${adminNoteCount?` ${adminNoteCount}`:''}</button>`:adminNoteCount?`<button data-admin-note-view-company="${base.id}" class="ghost admin-note-btn has-note" title="Nota do administrador">ADM ${adminNoteCount}</button>`:''}<button data-delete-company-line="${base.id}" class="danger" title="Excluir esta linha da competência aberta e da carteira futura">Excluir linha</button></div></div>`}
