async function saveCellNote(e){e.preventDefault();const t=state.cellNoteTarget;if(!t)return;if(!ensurePeriodEditable())return;const note=$('#cellNoteText').value.trim(),v=$('#cellNoteValidation');if(note.length>1000){v.textContent='A nota pode ter no máximo 1000 caracteres.';v.className='validation-msg error';return}const body={company_id:t.company_id,competence:t.competence,item_id:t.item_id,item_label:t.item_label,note};try{await queue('POST','/check-notes',body,async()=>{const company=companyById(body.company_id);if(company&&!company._snapshot)await ensureLocalSnapshot(company,body.competence);const prev=state.checks.find(x=>x.key===t.key)||{};await idb.put('checks',{status:'PENDING',...prev,...body,note:note||null,key:t.key,updated_at:new Date().toISOString()});state.checks=await idb.all('checks')});$('#cellNoteDialog').close();renderAll();toast(note?`Nota salva em ${t.item_label}.`:`Nota removida de ${t.item_label}.`);broadcastRefresh()}catch(err){v.textContent=err.message;v.className='validation-msg error'}}
