async function openRenameColumnDialog(itemId){if(!navigator.onLine)return toast('Renomear coluna exige conexão com o servidor.',true);if(!(await ensureAdminPeriodEditable('renomear colunas')))return;const owner=checklistColumnTargetOwner();if(state.user?.role==='ADMIN'&&!owner){toast('Selecione um responsável antes de renomear uma coluna.',true);return}const col=carteiraColumns(owner).find(c=>c.id===itemId);if(!col){toast('Coluna não encontrada nesta carteira.',true);return}state.renameColumnId=itemId;const who=state.user?.role==='ADMIN'?(ownerName(owner)||'responsável selecionado'):(state.user?.display_name||'sua carteira');$('#renameColumnScope').textContent=`${who} · título atual: ${col.label}`;$('#renameColumnTitle').value=col.label;$('#renameColumnValidation').textContent='';$('#renameColumnValidation').className='validation-msg';$('#renameColumnDialog').showModal();setTimeout(()=>{$('#renameColumnTitle').focus();$('#renameColumnTitle').select()},30)}

async function exportMonthlyXlsx(){
  if(!navigator.onLine)return toast('A exportação XLSX precisa de conexão com o servidor para reunir todos os dados da competência.',true);
  const competence=$('#competenceInput').value||monthNow();
  const params=new URLSearchParams({competence});
  if(state.user?.role==='ADMIN'){
    const owner=$('#ownerSelect').value||'';
    if(owner)params.set('owner_user_id',owner);
  }
  const btn=$('#exportMonthlyBtn');
  const old=btn?.textContent||'Exportar XLSX';
  if(btn){btn.disabled=true;btn.textContent='Exportando…'}
  try{
    const headers={};if(token())headers.Authorization='Bearer '+token();
    const r=await fetch(`${API}/export/monthly.xlsx?${params.toString()}`,{headers,cache:'no-store'});
    if(!r.ok){let msg=`Erro ${r.status}`;try{const d=await r.json();msg=d.error||msg}catch{}throw new Error(msg)}
    const blob=await r.blob();
    let filename=`Controle_Fiscal_${competence}.xlsx`;
    const cd=r.headers.get('Content-Disposition')||'';
    const utf=cd.match(/filename\*=UTF-8''([^;]+)/i);const plain=cd.match(/filename="([^"]+)"/i);
    if(utf){try{filename=decodeURIComponent(utf[1])}catch{}}else if(plain)filename=plain[1];
    const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
    toast(`Exportação de ${monthLabel(competence)} concluída.`);
  }catch(e){toast(e.message,true)}finally{if(btn){btn.disabled=false;btn.textContent=old}}
}

