function companySearchValues(c,monthly){const regimeCode=normalizedTaxRegimeCode(c.tax_regime),regimeLabel=canonicalTaxRegimeLabel(c.tax_regime);return[c.legal_name,c.cnpj,c.dominio_code,c.tax_regime,regimeLabel,regimeCode,c.envio,c.particularities,c.notes,monthly?.note,ownerName(c.owner_user_id)]}
function sortCompanies(bases,comp,cmap,smap,nmap){const mode=$('#sortSelect')?.value||state.sort||'NAME';const name=(base)=>String(companyAtCompetence(base,comp,smap).legal_name||'');const collator=new Intl.Collator('pt-BR',{sensitivity:'base',numeric:true});const rank={ALERT:0,PENDING:1,DONE:2};return [...bases].sort((a,b)=>{if(mode==='MANUAL'){if(state.user?.role==='ADMIN'&&!state.scope){const ownerCmp=collator.compare(ownerName(a.owner_user_id),ownerName(b.owner_user_id));if(ownerCmp)return ownerCmp}const oa=Number(companyAtCompetence(a,comp,smap).display_order)||Number.MAX_SAFE_INTEGER,ob=Number(companyAtCompetence(b,comp,smap).display_order)||Number.MAX_SAFE_INTEGER;if(oa!==ob)return oa-ob;return collator.compare(name(a),name(b))}if(mode==='PROGRESS_ASC'||mode==='PROGRESS_DESC'){const ca=companyAtCompetence(a,comp,smap),cb=companyAtCompetence(b,comp,smap),pa=companyState(ca,comp,cmap,nmap).progress,pb=companyState(cb,comp,cmap,nmap).progress;if(pa!==pb)return mode==='PROGRESS_ASC'?pa-pb:pb-pa}if(mode==='ATTENTION'){const ca=companyAtCompetence(a,comp,smap),cb=companyAtCompetence(b,comp,smap),ra=rank[companyState(ca,comp,cmap,nmap).overall]??9,rb=rank[companyState(cb,comp,cmap,nmap).overall]??9;if(ra!==rb)return ra-rb}return collator.compare(name(a),name(b))})}
