function visibleCompanies(comp,cmap,smap=snapshotMap(),nmap=monthlyNoteMap()){const q=$('#searchInput').value.trim().toLowerCase(),filter=$('#statusFilter')?.value||'ALL',regimeCode=regimeFilterCode();/* KEEPVIS01: trocou filtro/busca/ordem/mês/carteira = esquece as linhas mantidas */const keepCtx=[comp,filter,q,regimeCode,$('#sortSelect')?.value||state.sort||'NAME',state.scope||''].join('|');if(!(state.keepVisible instanceof Set)||state.keepVisibleCtx!==keepCtx){state.keepVisible=new Set();state.keepVisibleOrder=null;state.keepVisibleCtx=keepCtx}const keep=state.keepVisible;let keptOutside=0;const filtered=periodBaseCompanies(comp).filter(base=>{const c=companyAtCompetence(base,comp,smap),monthly=nmap.get(`${base.id}|${comp}`);const textOk=!q||companySearchValues(c,monthly).some(v=>String(v||'').toLowerCase().includes(q));if(!textOk)return false;if(regimeCode&&normalizedTaxRegimeCode(c.tax_regime)!==regimeCode)return false;if(filter==='ALL'||companyState(c,comp,cmap,nmap).overall===filter)return true;if(keep.has(companyIdKey(base.id))){keptOutside++;return true}return false});let sorted=sortCompanies(filtered,comp,cmap,smap,nmap);const statusSort=['ATTENTION','PROGRESS_ASC','PROGRESS_DESC'].includes($('#sortSelect')?.value||state.sort||'NAME');if(statusSort&&keep.size&&Array.isArray(state.keepVisibleOrder)){const pos=new Map(state.keepVisibleOrder.map((id,i)=>[id,i])),idx=new Map(sorted.map((b,i)=>[b,i]));sorted=[...sorted].sort((a,b)=>(pos.get(companyIdKey(a.id))??(1e9+idx.get(a)))-(pos.get(companyIdKey(b.id))??(1e9+idx.get(b))))}state.keepVisibleOrder=sorted.map(b=>companyIdKey(b.id));state.keptOutside=keptOutside;state.keepVisibleFrozen=statusSort&&keep.size>0;return sorted}
