function defaultChecklist(regime){regime=canonicalTaxRegimeLabel(regime);const map={'SIMPLES NACIONAL':['Saídas','Entradas','Simples','ISS','REINF','ICMS','DeSTDA','DIRBI','FUNRURAL','Enviado'],'LUCRO PRESUMIDO':['Saídas','Entradas','ISS','CSLL','IRPJ','ICMS','PIS/COFINS','REINF','EFD Contrib.','EFD ICMS/GIA','DIRBI','FUNRURAL','Aplicações','Enviado'],'LUCRO REAL':['Saídas','Entradas','ISS','CSLL','IRPJ','ICMS','PIS/COFINS','REINF','EFD Contrib.','EFD ICMS/GIA','DIRBI','FUNRURAL','Aplicações','Enviado'],'COOPERATIVA':['Saídas','Entradas','ISS','CSLL','IRPJ','ICMS','PIS/COFINS','REINF','EFD Contrib.','EFD ICMS/GIA','DIRBI','FUNRURAL','Aplicações','Enviado'],'OUTROS':['Saídas','Entradas','ISS','ICMS','REINF','Enviado']};return (map[regime]||map.OUTROS).map(label=>({id:slug(label),label}))}
const ALL_REGIMES=['SIMPLES NACIONAL','LUCRO PRESUMIDO','LUCRO REAL','COOPERATIVA','OUTROS'];
function regimeChecklistLabels(current,regime,keepKeys=new Set()){const defs=defaultChecklist(regime).map(i=>i.label),known=new Set(ALL_REGIMES.flatMap(r=>defaultChecklist(r).map(i=>slug(i.label)))),have=new Set(defs.map(slug)),out=[...defs];for(const l of current){const k=slug(l);if(have.has(k))continue;if(!known.has(k)||keepKeys.has(k)){out.push(l);have.add(k)}}return out}
