function applyRegimeChecklist(auto){const id=$('#companyId').value,comp=$('#competenceInput').value||monthNow(),co=(state.companies||[]).find(c=>companyIdKey(c.id)===companyIdKey(id)),existing=co?.checklist||[],current=$('#companyChecklist').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),keep=new Set();for(const ch of state.checks||[]){if(companyIdKey(ch.company_id)!==companyIdKey(id)||ch.competence!==comp)continue;if((ch.status&&ch.status!=='PENDING')||ch.note){const it=existing.find(i=>i.id===ch.item_id);keep.add(slug(it?.label||ch.item_label||''))}}const next=regimeChecklistLabels(current,$('#companyRegime').value,keep),curKeys=new Set(current.map(slug)),nextKeys=new Set(next.map(slug)),added=next.filter(l=>!curKeys.has(slug(l))),removed=current.filter(l=>!nextKeys.has(slug(l)));$('#companyChecklist').value=next.join('\n');state.companyChecklistRegimeMerge=true;updateCompanyChecklistHint(added.length||removed.length?`Itens ajustados para ${$('#companyRegime').value}${added.length?` · incluídos: ${added.join(', ')}`:''}${removed.length?` · retirados: ${removed.join(', ')}`:''}. Confira e clique em Salvar.`:(auto?'':'Os itens já correspondem ao regime selecionado.'))}
function slug(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||uid()}
function linesToChecklist(text,existing=[],opts={}){const labels=text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const oldByLabel=new Map(existing.map((i,idx)=>[i.label.toLowerCase(),{...i,idx}]));const usedOld=new Set(),assigned=new Array(labels.length);for(let idx=0;idx<labels.length;idx++){const hit=oldByLabel.get(labels[idx].toLowerCase());if(hit&&!usedOld.has(hit.id)){assigned[idx]=hit.id;usedOld.add(hit.id)}}for(let idx=0;idx<labels.length&&opts.positional!==false;idx++){if(assigned[idx])continue;const candidate=existing[idx];if(candidate&&!usedOld.has(candidate.id)){assigned[idx]=candidate.id;usedOld.add(candidate.id)}}const ids=new Set();return labels.map((label,idx)=>{let id=assigned[idx]||slug(label);while(ids.has(id))id=id+'-'+ids.size;ids.add(id);return{id,label}})}
