$('#companyCnpj').oninput=()=>{const el=$('#companyCnpj');el.value=formatCnpj(el.value);const d=onlyDigits(el.value),hint=$('#companyCnpjHint');if(!d){hint.textContent='Opcional.';hint.className='field-hint'}else if(d.length<14){hint.textContent=`${d.length}/14 dígitos`;hint.className='field-hint'}else if(validCnpj(d)){hint.textContent='CNPJ válido.';hint.className='field-hint ok'}else{hint.textContent='CNPJ inválido.';hint.className='field-hint error'}};
$('#companyForm').onsubmit=async e=>{e.preventDefault();if(dialogCompetenceChanged(state.companyDialogComp))return;if(!confirmLaterCompetence())return;const validation=$('#companyValidation');validation.textContent='';validation.className='validation-msg';const id=$('#companyId').value||uid();const existing=companyById(id);const owner=state.user.role==='ADMIN'?$('#companyOwner').value:state.user.id;const body={id,competence:$('#competenceInput').value||monthNow(),legal_name:$('#companyName').value.trim(),cnpj:onlyDigits($('#companyCnpj').value),dominio_code:$('#companyDominio').value.trim(),tax_regime:$('#companyRegime').value,envio:$('#companyEnvio').value.trim(),particularities:$('#companyParticularities').value.trim(),notes:$('#companyNotes').value.trim(),owner_user_id:owner,checklist:linesToChecklist($('#companyChecklist').value,existing?.checklist||[],{positional:!state.companyChecklistRegimeMerge})};if(!body.legal_name){validation.textContent='Informe o nome da empresa.';validation.className='validation-msg error';return}if(body.cnpj&&!validCnpj(body.cnpj)){validation.textContent='CNPJ inválido. Confira os 14 dígitos.';validation.className='validation-msg error';return}const duplicate=localDuplicate(body,existing?.id||'');if(duplicate){validation.textContent=duplicate;validation.className='validation-msg error';return}const method=existing?'PUT':'POST',path=existing?`/companies/${id}`:'/companies';try{if(historicalEditMode()){await api(path,{method,body:JSON.stringify(body)});await refreshFromServer(state.scope);renderAll()}else{await queue(method,path,body,async()=>{const peers=state.companies.filter(c=>companyIdKey(c.owner_user_id)===companyIdKey(owner)),localOrder=Number(existing?.display_order)||Math.max(0,...peers.map(c=>Number(c.display_order)||0))+1,localCompany={...(existing||{}),...body,id,display_order:localOrder,deleted:false};await idb.put('companies',localCompany);if(existing){const snaps=await idb.all('snapshots');for(const snap of snaps.filter(x=>x.company_id===id&&x.competence===body.competence)){await idb.put('snapshots',{...snap,legal_name:body.legal_name,cnpj:body.cnpj,dominio_code:body.dominio_code,tax_regime:body.tax_regime,envio:body.envio,particularities:body.particularities,notes:body.notes,checklist:body.checklist});}const labels=new Map(body.checklist.map(i=>[i.id,i.label]));const checks=await idb.all('checks');for(const check of checks.filter(x=>x.company_id===id&&labels.has(x.item_id)))await idb.put('checks',{...check,item_label:labels.get(check.item_id)});}else{await ensureLocalSnapshot(localCompany,body.competence)}state.companies=await idb.all('companies');state.snapshots=await idb.all('snapshots');state.checks=await idb.all('checks')})}$('#companyDialog').close();toast(historicalEditMode()?(existing?'Empresa atualizada somente nesta competência histórica.':'Empresa incluída somente nesta competência histórica.'):(existing?'Empresa atualizada; períodos já salvos permanecem congelados.':'Nova empresa incluída nesta competência e na carteira dos próximos períodos.'))}catch(err){validation.textContent=err.message;validation.className='validation-msg error'}};
async function deleteCompanyLine(id){if(!(await ensureAdminPeriodEditable('excluir esta linha')))return;const base=companyById(id);if(!base)return toast('Empresa não encontrada.',true);const comp=$('#competenceInput').value||monthNow();const hist=historicalEditMode(comp),msg=hist?`Excluir a linha de “${base.legal_name}” somente de ${monthLabel(comp)}?\n\nO cadastro atual e os períodos posteriores não serão alterados.`:`Excluir a linha de “${base.legal_name}” de ${monthLabel(comp)}?\n\nA empresa será removida da carteira a partir deste período. Competências já salvas anteriormente permanecerão preservadas no histórico.`;if(!confirm(msg))return;if(hist){await api(`/companies/${id}?competence=${encodeURIComponent(comp)}`,{method:'DELETE'});await refreshFromServer(state.scope);renderAll()}else{await queue('DELETE',`/companies/${id}?competence=${encodeURIComponent(comp)}`,null,async()=>{await idb.del('companies',id);await idb.del('snapshots',`${id}|${comp}`);state.companies=await idb.all('companies');state.snapshots=await idb.all('snapshots')})};if($('#companyDialog')?.open)$('#companyDialog').close();if(companyIdKey(state.companyPanelId)===companyIdKey(id))closeCompanyChecklistPanel();toast(hist?'Linha removida somente desta competência histórica.':'Linha excluída. O histórico de períodos já salvos foi preservado.')}
$('#deleteCompanyBtn').onclick=async()=>{const id=$('#companyId').value;if(id)await deleteCompanyLine(id)};

