$('#importBtn').onclick=async()=>{if(!navigator.onLine)return toast('A importação da planilha exige conexão com o servidor.',true);const owner=currentImportOwner();if(state.user.role==='ADMIN'&&!owner)return toast('Selecione primeiro o responsável que receberá as empresas importadas.',true);if(!(await ensureAdminPeriodEditable('importar empresas nesta competência')))return;$('#fileInput').click()};
$('#fileInput').onchange=async()=>{if(!ensurePeriodEditable()){ $('#fileInput').value=''; return }const f=$('#fileInput').files[0];if(!f)return;try{setSync('Lendo planilha…');const owner=currentImportOwner();const buf=await f.arrayBuffer();let binary='';const arr=new Uint8Array(buf);for(let i=0;i<arr.length;i+=0x8000)binary+=String.fromCharCode(...arr.subarray(i,i+0x8000));const data=await api('/parse-excel',{method:'POST',body:JSON.stringify({filename:f.name,content_base64:btoa(binary),owner_user_id:owner})});state.importPreview=data.companies||[];const ownerName=state.users.find(u=>u.id===owner)?.display_name||state.user.display_name;$('#importSummary').innerHTML=`<div class="import-counts"><span>${data.count} reconhecida(s)</span><span>${data.importable} nova(s)</span><span>${data.skipped} ignorada(s)</span></div>`;$('#importDestination').textContent=`Destino: ${ownerName} · Arquivo: ${f.name}`;$('#importWarnings').innerHTML=(data.warnings||[]).map(w=>`<p class="form-msg">${esc(w)}</p>`).join('');$('#importPreview').innerHTML='<table><thead><tr><th>Status</th><th>Empresa</th><th>CNPJ</th><th>Dom.</th><th>Regime</th><th>Envio</th><th>Motivo/Origem</th></tr></thead><tbody>'+state.importPreview.map(c=>`<tr class="${c.importable?'':'import-skip'}"><td><span class="import-status ${c.importable?'ok':'skip'}">${c.importable?'Importar':'Ignorar'}</span></td><td>${esc(c.legal_name)}</td><td>${esc(formatCnpj(c.cnpj||''))}</td><td>${esc(c.dominio_code)}</td><td>${esc(c.tax_regime)}</td><td>${esc(c.envio)}</td><td class="import-reason">${c.importable?`${esc(c.source_sheet)} · linha ${c.source_row}`:esc(c.duplicate_reason)}</td></tr>`).join('')+'</tbody></table>';$('#confirmImportBtn').disabled=!data.importable;$('#confirmImportBtn').textContent=data.importable?`Importar ${data.importable} empresa(s)`:'Nada para importar';$('#importDialog').showModal();setSync('Sincronizado','ok')}catch(e){toast(e.message,true);setSync('Erro','offline')}finally{$('#fileInput').value=''}};
$('#confirmImportBtn').onclick=async()=>{try{const rows=state.importPreview.filter(c=>c.importable!==false);if(!rows.length)return;const owner=currentImportOwner();const data=await api('/import-companies',{method:'POST',body:JSON.stringify({owner_user_id:owner,competence:$('#competenceInput').value||monthNow(),companies:rows})});$('#importDialog').close();const extra=data.skipped?.length?` ${data.skipped.length} registro(s) foram ignorados na revalidação.`:'';toast(`${data.imported} empresa(s) importada(s).${extra}`);await bootstrap(state.scope)}catch(e){toast(e.message,true)}};

