async function openAdminDashboard(){if(state.user?.role!=='ADMIN')return;const comp=$('#competenceInput').value||monthNow();if(!navigator.onLine)return toast('O Dashboard ADM exige conexão com o servidor.',true);try{state.adminDashboard=await api(`/admin/dashboard?competence=${encodeURIComponent(comp)}`);renderAdminDashboard();$('#adminDashboardDialog').showModal()}catch(e){toast(e.message,true)}}
function renderAdminDashboard(){const d=state.adminDashboard;if(!d)return;$('#adminDashboardMeta').textContent=`${monthLabel(d.competence)} · visão consolidada por responsável`;const t=d.totals||{},totalCards=[['Total',t.total||0,'total'],['Concluídas',t.done||0,'done'],['Alertas',t.alerts||0,'alert'],['Pendentes',t.pending||0,'pending'],['Com pendência',t.with_pending||0,'warning'],['Com observação',t.with_obs||0,'info'],['Nota ADM',t.admin_notes||0,'admin'],['Não iniciadas',t.not_started||0,'neutral']];$('#adminDashboardTotals').innerHTML=totalCards.map(([label,value,tone])=>`<div class="admin-dashboard-total ${tone}"><span>${label}</span><b>${value}</b></div>`).join('');$('#adminDashboardUsers').innerHTML=(d.users||[]).map(x=>{const pct=x.total?Math.round((x.done||0)*100/x.total):0;return `<button type="button" class="admin-user-card" data-dashboard-user="${x.user.id}"><div class="admin-user-card-head"><div><b>${esc(x.user.display_name)}</b><span>${x.total} empresa(s)</span></div><strong>${pct}%</strong></div><div class="admin-user-progress"><span style="width:${pct}%"></span></div><div class="admin-user-card-metrics"><span class="done"><b>${x.done}</b><small>Concluídas</small></span><span class="alert"><b>${x.alerts}</b><small>Alertas</small></span><span class="pending"><b>${x.pending}</b><small>Pendentes</small></span><span class="warning"><b>${x.with_pending}</b><small>C/ pendência</small></span><span class="info"><b>${x.with_obs}</b><small>C/ observação</small></span><span class="admin"><b>${x.admin_notes}</b><small>Nota ADM</small></span></div><div class="admin-user-card-foot"><span>Abrir carteira e checklist</span><b>→</b></div></button>`}).join('')||'<div class="empty">Nenhum usuário comum ativo.</div>';$$('[data-dashboard-user]').forEach(b=>b.onclick=()=>openUserChecks(b.dataset.dashboardUser,d.competence,'adminDashboardDialog'))}
async function openUserChecks(userId,comp,dialogId='',companyName=''){if(dialogId&&document.getElementById(dialogId)?.open)document.getElementById(dialogId).close();if(comp){$('#competenceInput').value=comp;localStorage.setItem('ht_competence',comp)}await bootstrap(userId);if(companyName){$('#searchInput').value=companyName;renderTable()}window.scrollTo({top:0,behavior:'smooth'})}
async function openAdminHistory(){if(state.user?.role!=='ADMIN')return;if(!navigator.onLine)return toast('O Histórico ADM exige conexão com o servidor.',true);try{state.adminHistory=await api('/admin/history');const sel=$('#adminHistoryUserFilter');sel.innerHTML='<option value="">Todos os usuários</option>'+state.users.filter(u=>u.role==='USER').map(u=>`<option value="${u.id}">${esc(u.display_name)}</option>`).join('');const comps=[...new Set((state.adminHistory.rows||[]).map(r=>r.competence))].sort().reverse();$('#adminHistoryCompetenceFilter').innerHTML='<option value="">Todas as competências</option>'+comps.map(c=>`<option value="${c}">${esc(monthLabel(c))}</option>`).join('');renderAdminHistory();$('#adminHistoryDialog').showModal()}catch(e){toast(e.message,true)}}
function renderAdminHistory(){const d=state.adminHistory;if(!d)return;const uid=$('#adminHistoryUserFilter').value||'',comp=$('#adminHistoryCompetenceFilter').value||'',rows=(d.rows||[]).filter(r=>(!uid||r.user_id===uid)&&(!comp||r.competence===comp)),notes=(d.notes||[]).filter(n=>(!uid||n.owner_user_id===uid)&&(!comp||n.competence===comp));$('#adminHistoryMonthly').innerHTML=rows.length?`<table class="admin-history-table"><thead><tr><th>Usuário</th><th>Competência</th><th>Total</th><th>Concl.</th><th>Alertas</th><th>Pend.</th><th>Com obs.</th><th>Nota ADM</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.user_name)}</b></td><td>${esc(monthLabel(r.competence))}</td><td>${r.total}</td><td>${r.done}</td><td>${r.alerts}</td><td>${r.pending}</td><td>${r.with_obs}</td><td>${r.admin_notes}</td><td><button type="button" data-admin-history-open-user="${r.user_id}" data-admin-history-open-comp="${r.competence}">Abrir checks</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Nenhum histórico para os filtros selecionados.</div>';$('#adminHistoryNotes').innerHTML=notes.length?`<table class="admin-history-table admin-note-history-table"><thead><tr><th>Usuário</th><th>Competência</th><th>Empresa</th><th>Item</th><th>Tipo</th><th>Nota</th><th>ADM</th><th>Data</th><th>Status</th><th></th></tr></thead><tbody>${notes.map(n=>`<tr class="${n.active===false?'archived':''}"><td>${esc(n.owner_name||'')}</td><td>${esc(monthLabel(n.competence))}</td><td><b>${esc(n.company_name||'')}</b></td><td>${esc(n.item_label||'Empresa / competência')}</td><td>${esc(adminNoteTypeLabel(n.note_type))}</td><td class="admin-history-note-text">${esc(n.note)}</td><td>${esc(n.created_by_name||'')}</td><td>${n.created_at?new Date(n.created_at).toLocaleString('pt-BR'):'-'}</td><td>${n.active===false?'Arquivada':'Ativa'}</td><td><button type="button" data-admin-note-history-open="${n.owner_user_id}" data-admin-note-history-comp="${n.competence}" data-admin-note-history-company="${esc(n.company_name||'')}">Abrir</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Nenhuma nota administrativa para os filtros selecionados.</div>';$$('[data-admin-history-open-user]').forEach(b=>b.onclick=()=>openUserChecks(b.dataset.adminHistoryOpenUser,b.dataset.adminHistoryOpenComp,'adminHistoryDialog'));$$('[data-admin-note-history-open]').forEach(b=>b.onclick=()=>openUserChecks(b.dataset.adminNoteHistoryOpen,b.dataset.adminNoteHistoryComp,'adminHistoryDialog',b.dataset.adminNoteHistoryCompany))}
function adminNotesForDialog(companyId,comp){return (state.adminNotes||[]).filter(n=>n.company_id===companyId&&n.competence===comp).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')))}
function openAdminNotes(companyId,itemId=null){const company=companyById(companyId);if(!company)return;const comp=$('#competenceInput').value||monthNow();state.adminNoteDialog={companyId,comp};$('#adminNoteTitle').textContent=`Notas ADM - ${company.legal_name}`;$('#adminNoteMeta').textContent=`${monthLabel(comp)} · ${ownerName(company.owner_user_id)||state.user.display_name}`;const select=$('#adminNoteTarget');select.innerHTML=`<option value="__ROW__">Empresa / competência</option>`+(company.checklist||[]).map(i=>`<option value="${esc(i.id)}">${esc(i.label)}</option>`).join('');select.value=itemId&&select.querySelector(`option[value="${CSS.escape(itemId)}"]`)?itemId:'__ROW__';$('#adminNoteType').value='MESSAGE';$('#adminNoteText').value='';$('#adminNoteForm').classList.toggle('hidden',state.user.role!=='ADMIN');renderAdminNoteDialog();$('#adminNoteDialog').showModal();if(state.user.role==='ADMIN')setTimeout(()=>$('#adminNoteText').focus(),30)}
function renderAdminNoteDialog(){const ctx=state.adminNoteDialog;if(!ctx)return;const notes=adminNotesForDialog(ctx.companyId,ctx.comp),box=$('#adminNoteExisting');if(!notes.length){box.innerHTML='<div class="empty">Nenhuma nota do administrador nesta competência.</div>';return}box.innerHTML=notes.map(n=>`<article class="admin-note-entry ${n.active===false?'archived':''} ${String(n.note_type||'').toLowerCase()}"><div class="admin-note-entry-head"><span class="admin-note-type">${esc(adminNoteTypeLabel(n.note_type))}</span><b>${esc(n.item_label||'Empresa / competência')}</b><span>${n.created_at?new Date(n.created_at).toLocaleString('pt-BR'):''}</span></div><p>${esc(n.note)}</p><div class="admin-note-entry-foot"><span>Por ${esc(n.created_by_name||'Administrador')}</span>${n.active===false?'<span>Arquivada</span>':state.user.role==='ADMIN'?`<button type="button" data-archive-admin-note="${n.id}">Arquivar</button>`:'<span>Ativa</span>'}</div></article>`).join('');box.querySelectorAll('[data-archive-admin-note]').forEach(b=>b.onclick=()=>archiveAdminNote(b.dataset.archiveAdminNote))}
async function archiveAdminNote(id){if(state.user.role!=='ADMIN'||!confirm('Arquivar esta nota? Ela continuará registrada no Histórico ADM.'))return;await queue('DELETE',`/admin-notes/${id}`,null,async()=>{const n=state.adminNotes.find(x=>x.id===id);if(n)await idb.put('adminNotes',{...n,active:false,archived_at:new Date().toISOString()});state.adminNotes=await idb.all('adminNotes')});renderAdminNoteDialog();toast('Nota arquivada. O registro permanece no histórico.')}
async function saveAdminNote(){if(state.user.role!=='ADMIN')return;if(!ensurePeriodEditable())return;const ctx=state.adminNoteDialog;if(!ctx)return;const note=$('#adminNoteText').value.trim();if(!note)return toast('Digite a nota do administrador.',true);const itemId=$('#adminNoteTarget').value||'__ROW__',company=state.companies.find(c=>c.id===ctx.companyId),itemLabel=itemId==='__ROW__'?'Empresa / competência':company?.checklist?.find(i=>i.id===itemId)?.label||itemId,body={id:uid(),company_id:ctx.companyId,competence:ctx.comp,item_id:itemId,note_type:$('#adminNoteType').value,note};await queue('POST','/admin-notes',body,async()=>{await ensureLocalSnapshot(company,ctx.comp);await idb.put('adminNotes',{...body,item_label:itemLabel,active:true,created_by:state.user.id,created_by_name:state.user.display_name,owner_user_id:company.owner_user_id,owner_name:ownerName(company.owner_user_id),company_name:company.legal_name,created_at:new Date().toISOString()});state.adminNotes=await idb.all('adminNotes')});$('#adminNoteText').value='';renderAdminNoteDialog();toast('Nota do administrador registrada e destacada no checklist.')}

function alertFormSelectedIds(){return $$('[data-alert-target-user]:checked').map(x=>x.value)}
function updateAlertAudienceUi(){const all=$('#newAlertTargetAll')?.checked!==false;$$('[data-alert-target-user]').forEach(x=>x.disabled=all);$('#newAlertTargets')?.classList.toggle('is-disabled',all);const hint=$('#alertAudienceHint');if(hint)hint.textContent=all?'O alerta será exibido a todas as contas ativas, inclusive administradores.':`${alertFormSelectedIds().length} usuário(s) selecionado(s).`}
function renderAlertTargetOptions(selectedIds=null,force=false){const box=$('#newAlertTargets');if(!box)return;const users=(state.users||[]).filter(u=>u.active).sort((a,b)=>String(a.display_name||'').localeCompare(String(b.display_name||''),'pt-BR')),signature=users.map(u=>`${u.id}:${u.display_name}:${u.role}`).join('|'),selected=new Set(selectedIds===null?alertFormSelectedIds():selectedIds.map(String));if(!force&&box.dataset.signature===signature&&box.children.length){updateAlertAudienceUi();return}box.dataset.signature=signature;box.innerHTML=users.map(u=>`<label class="alert-target-option"><input type="checkbox" data-alert-target-user value="${esc(u.id)}" ${selected.has(String(u.id))?'checked':''}><span><b>${esc(u.display_name)}</b><small>${u.role==='ADMIN'?'Administrador':'Usuário'}${String(u.id)===String(state.user?.id)?' · você':''}</small></span></label>`).join('')||'<small class="muted">Nenhuma conta ativa disponível.</small>';$$('[data-alert-target-user]').forEach(x=>x.onchange=()=>{updateAlertAudienceUi();updateAlertPreview()});updateAlertAudienceUi()}
function alertEditorFont(){const n=Number.parseInt($('#newAlertFontSize')?.value,10);return Number.isFinite(n)?Math.max(ALERT_FONT_MIN,Math.min(ALERT_FONT_MAX,n)):ALERT_FONT_DEFAULT}
function setAlertEditorFont(value){const n=Math.max(ALERT_FONT_MIN,Math.min(ALERT_FONT_MAX,Number.parseInt(value,10)||ALERT_FONT_DEFAULT));if($('#newAlertFontSize'))$('#newAlertFontSize').value=String(n);if($('#newAlertFontValue'))$('#newAlertFontValue').textContent=`${n} px`;if($('#newAlertFontDown'))$('#newAlertFontDown').disabled=n<=ALERT_FONT_MIN;if($('#newAlertFontUp'))$('#newAlertFontUp').disabled=n>=ALERT_FONT_MAX;updateAlertPreview()}
