function showInstallHelp(){const box=$('#installHelpText'),dlg=$('#installHelpDialog');if(!box||!dlg)return;const secure=pwaSecureContext();if(IOS_DEVICE){box.innerHTML='<p><b>iPhone/iPad:</b> abra esta página no Safari, toque em <b>Compartilhar</b> e escolha <b>Adicionar à Tela de Início</b>.</p><p>Ao abrir pelo ícone instalado, o Controle Fiscal usa a visualização de aplicativo, sem a barra normal do navegador.</p>'}else if(!secure){box.innerHTML='<p>O app já está otimizado para celular e pode ser usado normalmente nesta rede.</p><p><b>Para instalar como PWA sem a barra de URL no celular, o endereço de rede precisa usar HTTPS.</b> Em HTTP, o Chrome pode permitir apenas um atalho que continua abrindo como página do navegador.</p>'}else{box.innerHTML='<p>No Chrome, abra o menu <b>⋮</b> e escolha <b>Instalar app</b> ou <b>Adicionar à tela inicial</b>.</p><p>Depois, abra pelo ícone instalado para usar a interface standalone, sem a barra de URL.</p>'}dlg.showModal()}
